/* * 需求：把G:\\a.avi复制到G:\\b.avi中 *  * 字节流四种方式复制文件： * 基本字节流一次读写一个字节：    共耗时24199毫秒 * 基本字节流一次读写一个字节数组：    共耗时40毫秒 * 高效字节流一次读写一个字节：     共耗时200毫秒 * 高效字节流一次读写一个字节数组：     共耗时17毫秒 */public class CopyAVIDemo &#123;    public static void main(String[] args) throws IOException &#123;        long start = System.currentTimeMillis();        method4(&quot;G:\\a.avi&quot;, &quot;G:\\b.avi&quot;);        long end = System.currentTimeMillis();        System.out.println(&quot;共耗时&quot; + (end - start) + &quot;毫秒&quot;);    &#125;    // 高效字节流一次读写一个字节数组,共耗时17毫秒    public static void method4(String string, String string2) throws IOException &#123;        BufferedInputStream bis = new BufferedInputStream(new FileInputStream(string));        BufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(string2, true));        byte[] bys = new byte[1024];        int len = 0;        while ((len = bis.read(bys)) != -1) &#123;            bos.write(bys, 0, len);        &#125;        bos.close();        bis.close();    &#125;    // 高效字节流一次读写一个字节,共耗时200毫秒    public static void method3(String string, String string2) throws IOException &#123;        BufferedInputStream bis = new BufferedInputStream(new FileInputStream(string));        BufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(string2));        int by = 0;        while ((by = bis.read()) != -1) &#123;            bos.write(by);        &#125;        bos.close();        bis.close();    &#125;    // 基本字节流一次读写一个字节数组,共耗时40毫秒    public static void method2(String string, String string2) throws IOException &#123;        FileInputStream fis = new FileInputStream(string);        FileOutputStream fos = new FileOutputStream(string2);        byte[] bys = new byte[1024];        int len = 0;        while ((len = fis.read(bys)) != -1) &#123;            fos.write(bys, 0, len);        &#125;        fos.close();        fis.close();    &#125;    // 基本字节流一次读写一个字节,共耗时24199毫秒    public static void method1(String string, String string2) throws IOException &#123;        FileInputStream fis = new FileInputStream(string);        FileOutputStream fos = new FileOutputStream(string2);        int by = 0;        while ((by = fis.read()) != -1) &#123;            fos.write(by);        &#125;        fos.close();        fis.close();    &#125;&#125;

字符流介绍​		字节流操作中文数据不是特别的方便，所以就出现了转换流。转换流的作用就是把字节流转换字符流来使用。
​		转换流其实是一个字符流。
​		字符流 &#x3D; 字节流 + 编码表
编码表就是由字符和对应的数值组成的一张表。
1、计算机只能识别二进制数据，早期由来是电信号。为了方便应用计算机，让它可以识别各个国家的文字，就将各个国家的文字用数字来表示，并一 一对应，形成一张表。
　　　　ASCII：美国标准信息交换码。用一个字节的7位可以表示。 
　　　　ISO-8859-1：拉丁码表，欧洲码表。用一个字节的8位表示。
　　　　GB2312：中国的中文编码表。
　　　　GBK：中国的中文编码表升级，融合了更多的中文文字符号。
　　　　GB18030：GBK的取代版本
　　　　BIG-5码 ：通行于台湾、香港地区的一个繁体字编码方案，俗称”大五码”。地区标准号为：CNS11643，这就是人们讲的BIG-5码。
　　　　Unicode：国际标准码，融合了多种文字。所有文字都用两个字节来表示,Java语言使用的就是unicode
　　　　UTF-8：最多用三个字节来表示一个字符。
　　　　UTF-8不同，它定义了一种”区间规则”，这种规则可以和ASCII编码保持最大程度的兼容：
　　　　　　它将Unicode编码为00000000-0000007F的字符，用单个字节来表示
　　　　　　它将Unicode编码为00000080-000007FF的字符用两个字节表示
　　　　　　它将Unicode编码为00000800-0000FFFF的字符用3字节表示
2、字符串中的编码问题
　　　　编码：把能看懂的变成看不懂的
　　　　　　String – byte[]：使用String的构造方法
　　　　　　public byte[] getBytes(Charset charset)：使用给定的 charset （字符集）将此 String 编码到 byte 序列，并将结果存储到新的 byte 数组。
　　　　解码：把看不懂的变成能看懂的
　　　　　　byte[] – String：使用String的成员方法
　　　　　　public String(byte[] bytes, String charsetName):通过使用指定的 charset （字符集）解码指定的 byte 数组，构造一个新的 String。
/* *         发送端：今 -- 数值 -- 二进制 -- 发出去 *         接收端：接收 -- 二进制 -- 十进制 -- 数值 -- 字符 -- 今 * 编码问题简单，只要编码解码的格式是一致的。 */public class StringDemo &#123;    public static void main(String[] args) throws UnsupportedEncodingException &#123;        String s = &quot;你好&quot;;        // String -- byte[]        byte[] bys1 = s.getBytes(); //使用默认字符集编码 [-60, -29, -70, -61]        byte[] bys2 = s.getBytes(&quot;GBK&quot;); // [-60, -29, -70, -61]        byte[] bys3 = s.getBytes(&quot;UTF-8&quot;); // [-28, -67, -96, -27, -91, -67]        System.out.println(Arrays.toString(bys1));        System.out.println(Arrays.toString(bys2));        System.out.println(Arrays.toString(bys3));        // byte[] -- String        String ss1 = new String(bys1); // 你好        String ss2 = new String(bys2, &quot;GBK&quot;); // 你好        String ss3 = new String(bys1, &quot;UTF-8&quot;); // ???        System.out.println(ss1);        System.out.println(ss2);        System.out.println(ss3);    &#125;&#125; 

IO流中的编码问题​		编码问题其实很简单，编码只要一致即可
public class OutputStreamWriterDemo &#123;    public static void main(String[] args) throws IOException &#123;        // 创建对象        OutputStreamWriter osw1 = new OutputStreamWriter(new FileOutputStream(&quot;osw.txt&quot;)); // 默认GBK        OutputStreamWriter osw2 = new OutputStreamWriter(new FileOutputStream(&quot;osw.txt&quot;), &quot;GBK&quot;); // 指定GBK        OutputStreamWriter osw3 = new OutputStreamWriter(new FileOutputStream(&quot;osw.txt&quot;), &quot;UTF-8&quot;); // 指定UTF-8        InputStreamReader isr1 = new InputStreamReader(new FileInputStream(&quot;osw.txt&quot;));        InputStreamReader isr2 = new InputStreamReader(new FileInputStream(&quot;osw.txt&quot;), &quot;GBK&quot;);        InputStreamReader isr3 = new InputStreamReader(new FileInputStream(&quot;osw.txt&quot;), &quot;UTF-8&quot;);        // 写数据        osw2.write(&quot;中国&quot;);// 父类的方法，写入字符串                // 释放资源        osw1.close();        osw2.close();        osw3.close();        // 读取数据,一次读取一个字符        int ch = 0;        while ((ch = isr3.read()) != -1) &#123;            System.out.println(ch);        &#125;        isr1.close();        isr2.close();        isr3.close();    &#125;&#125;

OutputStreamWriter字符流通向字节流的桥梁。按指定字符集写入字符
　　构造方法：
　　　　public OutputStreamWriter(OutputStream out)：创建使用默认字符编码的 OutputStreamWriter。
　　　　public OutputStreamWriter(OutputStream out, String charsetName)：创建使用指定字符集的 OutputStreamWriter。指定编码。
　　成员方法：
　　　　public void write(int c)：写入单个字符。
　　　　public void write(char[] cbuf)：写入字符数组。是父类中的方法
　　　　public void write(char[] cbuf, int off, int len)：写入字符数组的某一部分。
　　　　public void write(String str)：写入字符串。是父类中的方法
　　　　public void write(String str, int off, int len)：写入字符串的某一部分。
/* * close()和flush()的区别? * A:close():先刷新一次缓冲区, 再关闭流对象,流对象不可以继续再使用了。 * B:flush():仅仅刷新缓冲区,流对象还可以继续使用。 */public class OutputStreamWriterDemo &#123;    public static void main(String[] args) throws IOException &#123;        // 创建对象        OutputStreamWriter osw = new OutputStreamWriter(new FileOutputStream(&quot;osw.txt&quot;, true));        // 写数据        osw.write(&#x27;a&#x27;);        osw.write(97);        char[] chs = &#123; &#x27;a&#x27;, &#x27;b&#x27;, &#x27;c&#x27;, &#x27;d&#x27;, &#x27;e&#x27; &#125;;        osw.write(chs);        osw.write(chs, 1, 3);        osw.write(&quot;我爱林青霞\r\n&quot;);        osw.write(&quot;我爱林青霞&quot;, 2, 3);        // 刷新缓冲区        osw.flush();        osw.write(&quot;我爱林青霞&quot;, 2, 3);        // 释放资源        osw.close();        // osw.write(&quot;我爱林青霞&quot;, 2, 3);// java.io.IOException: Stream closed    &#125;&#125; 

InputStreamReader字节流通向字符流的桥梁。按照指定字符集读取字符 
　　构造方法：
　　　　public InputStreamReader(InputStream in)：创建一个使用默认字符集的 InputStreamReader。
　　　　public InputStreamReader(InputStream in, String charsetName)：创建使用指定字符集的 InputStreamReader。
　　成员方法：
　　　　public int read()：读取单个字符。返回：读取的字符，如果已到达流的末尾，则返回 -1 。一次读取一个字符
　　　　public int read(char[] cbuf)：将字符读入数组。返回：读取的字符数，如果已到达流的末尾，则返回 -1。是父类中的方法。一次读取一个字符数组
　　　　public int read(char[] cbuf, int offset, int length)：将字符读入数组中的某一部分。返回：读取的字符数，如果已到达流的末尾，则返回 -1 。
public class InputStreamReaderDemo &#123;    public static void main(String[] args) throws IOException &#123;        // 创建对象        InputStreamReader isr = new InputStreamReader(new FileInputStream(&quot;osw.txt&quot;));        // 一次读取一个字符//        int ch = 0;//        while ((ch = isr.read()) != -1) &#123;//            System.out.print((char) ch);//        &#125;        // 一次读取一个字符数组        char[] chs = new char[1024];        int len = 0;        while ((len = isr.read(chs)) != -1) &#123;            System.out.print(new String(chs, 0, len));        &#125;        // 释放资源        isr.close();    &#125;&#125;

FileWriter和FileReader/* * 由于我们常见的操作都是使用本地默认编码，所以，不用指定编码。 * 而转换流的名称有点长，所以，Java就提供了其子类供我们使用。 * OutputStreamWriter = FileOutputStream + 编码表(GBK) * FileWriter = FileOutputStream + 编码表(GBK) *  * InputStreamReader = FileInputStream + 编码表(GBK) * FileReader = FileInputStream + 编码表(GBK) */public class CopyFileDemo &#123;    public static void main(String[] args) throws IOException &#123;        // 封装数据源        FileReader fr = new FileReader(&quot;a.txt&quot;);        // 封装目的地        FileWriter fw = new FileWriter(&quot;b.txt&quot;);        // 一次读取一个字符//        int ch = 0;//        while ((ch = fr.read()) != -1) &#123;//            fw.write(ch);//        &#125;        // 一次读取一个字符数组        char[] chs = new char[1024];        int len = 0;        while ((len = fr.read(chs)) != -1) &#123;            fw.write(chs, 0, len);            fw.flush();        &#125;        // 释放资源        fw.close();        fr.close();    &#125;&#125; 

字符缓冲流 　　A: BufferedWriter：字符缓冲输出流。将文本写入字符输出流，缓冲各个字符，从而提供单个字符、数组和字符串的高效写入。 可以指定缓冲区的大小，或者接受默认的大小。在大多数情况下，默认值就足够大了。 
　　　　构造方法：
　　　　　　public BufferedWriter(Writer out)：创建一个使用默认大小输出缓冲区的缓冲字符输出流。
　　　　　　public BufferedWriter(Writer out, int sz)：创建一个使用给定大小输出缓冲区的新缓冲字符输出流。
　　　　特殊方法：
　　　　　　public void newLine()：写入一个行分隔符。行分隔符字符串由系统属性 line.separator 定义，并且不一定是单个新行 (‘\n’) 符。
 　　B: BufferedReader：字符缓冲输入流。从字符输入流中读取文本，缓冲各个字符，从而实现字符、数组和行的高效读取。可以指定缓冲区的大小，或者可使用默认的大小。大多数情况下，默认值就足够大了。 
　　　　构造方法：
　　　　　　public BufferedReader(Reader in)：创建一个使用默认大小输入缓冲区的缓冲字符输入流。
　　　　　　public BufferedReader(Reader in, int sz)：创建一个使用指定大小输入缓冲区的缓冲字符输入流。
　　　　特殊方法：
　　　　　　public String readLine()：读取一个文本行。通过下列字符之一即可认为某行已终止：换行 (‘\n’)、回车 (‘\r’) 或回车后直接跟着换行。
　　　　　　　　　　　　　　　　　　返回：包含该行内容的字符串，不包含任何行终止符，如果已到达流末尾，则返回 null。
public class BufferedWriterDemo &#123;    public static void main(String[] args) throws IOException &#123;        // BufferedWriter(Writer out)        // BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(&quot;bw.txt&quot;)));        BufferedWriter bw = new BufferedWriter(new FileWriter(&quot;bw.txt&quot;));        bw.write(&quot;hello&quot;);        bw.write(&quot;world&quot;);        bw.write(&quot;java&quot;);        bw.flush();        bw.close();    &#125;&#125; 



public class BufferedReaderDemo &#123;    public static void main(String[] args) throws IOException &#123;        // 创建字符缓冲输入流对象        // BufferedReader(Reader in)        BufferedReader br = new BufferedReader(new FileReader(&quot;bw.txt&quot;));        // 方式1        int ch = 0;        while ((ch = br.read()) != -1) &#123;            System.out.print((char) ch);        &#125;        // 方式2//        char[] chs = new char[1024];//        int len = 0;//        while ((len = br.read(chs)) != -1) &#123;//            System.out.print(new String(chs, 0, len));//        &#125;        // 释放资源        br.close();    &#125;&#125;



/* * 字符缓冲流的特殊方法： */public class BufferedDemo &#123;    public static void main(String[] args) throws IOException &#123;        // write();        read();    &#125;    public static void read() throws IOException &#123;        // 创建字符缓冲输入流对象        BufferedReader br = new BufferedReader(new FileReader(&quot;bw.txt&quot;));        // public String readLine()：一次读取一行数据        String line = null;        while ((line = br.readLine()) != null) &#123;            System.out.println(line);// 不包含任何行终止符，所以用println。        &#125;                //释放资源        br.close();    &#125;    public static void write() throws IOException &#123;        // 创建字符缓冲输出流对象        BufferedWriter bw = new BufferedWriter(new FileWriter(&quot;bw.txt&quot;));        for (int x = 0; x &lt; 10; x++) &#123;            bw.write(&quot;hello&quot; + x);            // bw.write(&quot;\r\n&quot;);            bw.newLine();// 由系统属性决定换行符(行分隔符)            bw.flush();        &#125;        bw.close();    &#125;&#125;



/* * 需求：把当前项目目录下的a.txt内容复制到当前项目目录下的b.txt中 *  * 数据源： *         a.txt -- 读取数据 -- 字符转换流 -- InputStreamReader -- FileReader -- BufferedReader * 目的地： *         b.txt -- 写出数据 -- 字符转换流 -- OutputStreamWriter -- FileWriter -- BufferedWriter */public class CopyFileDemo &#123;    public static void main(String[] args) throws IOException &#123;        // 封装数据源        BufferedReader br = new BufferedReader(new FileReader(&quot;a.txt&quot;));        // 封装目的地        BufferedWriter bw = new BufferedWriter(new FileWriter(&quot;b.txt&quot;));        // 两种方式其中的一种:一次读取一个字符数组        char[] chs = new char[1024];        int len = 0;        while ((len = br.read(chs)) != -1) &#123;            bw.write(chs, 0, len);            bw.flush();        &#125;        // 释放资源        bw.close();        br.close();    &#125;&#125;/************************************************************************************/public class CopyFileDemo2 &#123;    public static void main(String[] args) throws IOException &#123;        // 封装数据源        BufferedReader br = new BufferedReader(new FileReader(&quot;a.txt&quot;));        // 封装目的地        BufferedWriter bw = new BufferedWriter(new FileWriter(&quot;b.txt&quot;));        // 读写数据        String line = null;        while ((line = br.readLine()) != null) &#123;            bw.write(line);            bw.newLine();            bw.flush();        &#125;        // 释放资源        bw.close();        br.close();    &#125;&#125;

