/* * 可以读写基本数据类型的数据 * 数据输入流：DataInputStream *             DataInputStream(InputStream in) * 数据输出流：DataOutputStream *             DataOutputStream(OutputStream out)  */public class DataStreamDemo &#123;    public static void main(String[] args) throws IOException &#123;        // 写//        write();        // 读        read();    &#125;    private static void read() throws IOException &#123;        // DataInputStream(InputStream in)        // 创建数据输入流对象        DataInputStream dis = new DataInputStream(new FileInputStream(&quot;dos.txt&quot;));        // 读数据        byte b = dis.readByte();        short s = dis.readShort();        int i = dis.readInt();        long l = dis.readLong();        float f = dis.readFloat();        double d = dis.readDouble();        char c = dis.readChar();        boolean bb = dis.readBoolean();        // 释放资源        dis.close();        System.out.println(b);        System.out.println(s);        System.out.println(i);        System.out.println(l);        System.out.println(f);        System.out.println(d);        System.out.println(c);        System.out.println(bb);    &#125;    private static void write() throws IOException &#123;        // DataOutputStream(OutputStream out)        // 创建数据输出流对象        DataOutputStream dos = new DataOutputStream(new FileOutputStream(&quot;dos.txt&quot;));        // 写数据了        dos.writeByte(10);        dos.writeShort(100);        dos.writeInt(1000);        dos.writeLong(10000);        dos.writeFloat(12.34F);        dos.writeDouble(12.56);        dos.writeChar(&#x27;a&#x27;);        dos.writeBoolean(true);        // 释放资源        dos.close();    &#125;&#125;

内存操作流内存操作流
一、有些时候我们操作完毕后，未必需要产生一个文件，就可以使用内存操作流。例如：从数据库中取出二进制的文件，会用到 ByteArrayInputStream 。
二、三种
　　A:ByteArrayInputStream,ByteArrayOutputStream
　　　　ByteArrayInputStream：包含一个内部缓冲区，该缓冲区包含从流中读取的字节。内部计数器跟踪 read 方法要提供的下一个字节。
　　　　　　　　　　　　　　　关闭 ByteArrayInputStream 无效。此类中的方法在关闭此流后仍可被调用，而不会产生任何 IOException。
　　B:CharArrayReader,CharArrayWriter
　　C:StringReader,StringWriter
/* * 内存操作流：用于处理临时存储信息的，程序结束，数据就从内存中消失。 * 字节数组： *         ByteArrayInputStream *         ByteArrayOutputStream * 字符数组： *         CharArrayReader *         CharArrayWriter * 字符串： *         StringReader *         StringWriter */public class ByteArrayStreamDemo &#123;    public static void main(String[] args) throws IOException &#123;        // 写数据        // ByteArrayOutputStream()        ByteArrayOutputStream baos = new ByteArrayOutputStream();        // 写数据        for (int x = 0; x &lt; 10; x++) &#123;            baos.write((&quot;hello&quot; + x).getBytes());        &#125;        // 释放资源        // 通过查看源码我们知道这里什么都没做，所以根本不需要close()        // baos.close();        // public byte[] toByteArray()        byte[] bys = baos.toByteArray();        // 读数据        // ByteArrayInputStream(byte[] buf)        ByteArrayInputStream bais = new ByteArrayInputStream(bys);        int by = 0;        while ((by = bais.read()) != -1) &#123;            System.out.print((char) by);        &#125;        // bais.close();    &#125;&#125;

打印流(掌握)一、字节打印流，字符打印流
二、特点：
　　A:只操作目的地,不操作数据源
　　B:可以操作任意类型的数据
　　C:如果启用了自动刷新，在调用println()方法的时候，能够换行并刷新
　　D:可以直接操作文件
　　　　问题：哪些流可以直接操作文件呢?
　　　　看API，如果其构造方法能够同时接收File和String类型的参数，一般都是可以直接操作文件的
三、复制文本文件
public class PrintWriterDemo &#123;    public static void main(String args[]) throws IOException &#123;        BufferedReader br = new BufferedReader(new FileReader(&quot;a.txt&quot;));        PrintWriter pw = new PrintWriter(new FileWriter(&quot;b.txt&quot;), true);        String line = null;        while ((line = br.readLine()) != null) &#123;            pw.println(line);        &#125;        pw.close();        br.close();    &#125;&#125;



/* * 打印流 * 字节流打印流    PrintStream * 字符打印流        PrintWriter *  * 打印流的特点： *         A:只有写数据的，没有读取数据。只能操作目的地，不能操作数据源。 *         B:可以操作任意类型的数据。 *         C:如果启动了自动刷新，能够自动刷新。 *         D:该流是可以直接操作文本文件的。 *             哪些流对象是可以直接操作文本文件的呢? *             FileInputStream *             FileOutputStream *             FileReader *             FileWriter *             PrintStream *             PrintWriter *             看API,查流对象的构造方法，如果同时有File类型和String类型的参数，一般来说就是可以直接操作文件的。 *  *             流： *                 基本流：就是能够直接读写文件的 *                 高级流：在基本流基础上提供了一些其他的功能 */public class PrintWriterDemo &#123;    public static void main(String[] args) throws IOException &#123;        // 作为Writer的子类使用        PrintWriter pw = new PrintWriter(&quot;test.txt&quot;);        pw.write(&quot;hello&quot;);        pw.write(&quot;world&quot;);        pw.write(&quot;java&quot;);        pw.close();    &#125;&#125;



/* * 1:可以操作任意类型的数据。 *         print() *         println() * 2:启动自动刷新 *         PrintWriter pw = new PrintWriter(new FileWriter(&quot;pw2.txt&quot;), true); *         还是应该调用println()的方法才可以 *         这个时候不仅仅自动刷新了，还实现了数据的换行。 *  *         println() *        其实等价于于： *        bw.write(); *        bw.newLine();         *        bw.flush(); */public class PrintWriterDemo2 &#123;    public static void main(String[] args) throws IOException &#123;        // 创建打印流对象        // PrintWriter pw = new PrintWriter(&quot;pw2.txt&quot;);        PrintWriter pw = new PrintWriter(new FileWriter(&quot;test.txt&quot;), true);        // write()是搞不定的，怎么办呢?        // 我们就应该看看它的新方法//        pw.print(true);//        pw.print(100);//        pw.print(&quot;hello&quot;);        pw.println(&quot;hello&quot;);        pw.println(true);        pw.println(100);        pw.close();    &#125;&#125;



/* * 需求：DataStreamDemo.java复制到Copy.java中 * 数据源： *         DataStreamDemo.java -- 读取数据 -- FileReader -- BufferedReader * 目的地： *         Copy.java -- 写出数据 -- FileWriter -- BufferedWriter -- PrintWriter */public class CopyFileDemo &#123;    public static void main(String[] args) throws IOException &#123;        // 以前的版本        // 封装数据源//        BufferedReader br = new BufferedReader(new FileReader(&quot;DataStreamDemo.java&quot;));//        // 封装目的地//        BufferedWriter bw = new BufferedWriter(new FileWriter(&quot;Copy.java&quot;));////        String line = null;//        while ((line = br.readLine()) != null) &#123;//            bw.write(line);//            bw.newLine();//            bw.flush();//        &#125;////        bw.close();//        br.close();        // 打印流的改进版        // 封装数据源        BufferedReader br = new BufferedReader(new FileReader(&quot;DataStreamDemo.java&quot;));        // 封装目的地        PrintWriter pw = new PrintWriter(new FileWriter(&quot;Copy.java&quot;), true);        String line = null;        while ((line = br.readLine()) != null) &#123;            pw.println(line);        &#125;        pw.close();        br.close();    &#125;&#125;

标准输入输出流一、System类下面有这样的两个字段
​		in	 标准输入流
​		out  标准输出流
二、三种键盘录入方式
　　A:main方法的args接收参数
　　B:System.in通过BufferedReader进行包装
