public class Test &#123;    public static void main(String[] args) &#123;        Account account = new Account(&quot;260731000&quot;, 100L);        Draw yourselfDraw = new Draw(account, 50L);        Thread yourself = new Thread(yourselfDraw, &quot;Yourself&quot;);        Draw girlFriendDraw = new Draw(account, 31L);        Thread girlFriend = new Thread(girlFriendDraw, &quot;GirlFriend&quot;);        yourself.start();        girlFriend.start();    &#125;&#125;@Dataclass Account &#123;    private String name;    private long money;    private final ReentrantLock lock = new ReentrantLock(true);    public Account(String name, long money) &#123;        this.name = name;        this.money = money;    &#125;&#125;class Draw implements Runnable &#123;    private Account account;    private long drawMoney; // 取款金额    public Draw(Account account, long drawMoney) &#123;        this.account = account;        this.drawMoney = drawMoney;    &#125;    @Override    public void run() &#123;        // synchronized(被锁对象)：锁的对象就是数据修改的对象        try &#123;            account.getLock().lockInterruptibly();            if (account.getMoney() - drawMoney &lt; 0) &#123;                System.out.println(Thread.currentThread().getName() + &quot;余额不足&quot;);                return;            &#125;            // sleep模拟取钱过程            try &#123;                TimeUnit.SECONDS.sleep(1L);            &#125; catch (InterruptedException e) &#123;                e.printStackTrace();            &#125;            System.out.printf(&quot;%s 账户余额: %d \t 取款金额: %d \t 剩余金额: %d \t 取款人: %s \n&quot;,                    account.getName(),                    account.getMoney(),                    drawMoney,                    account.getMoney() - drawMoney,                    Thread.currentThread().getName());            account.setMoney(account.getMoney() - drawMoney);        &#125; catch (InterruptedException e) &#123;            e.printStackTrace();        &#125; finally &#123;            account.getLock().unlock();            account.getLock().unlock(); // 抛出： IllegalMonitorStateException – 如果当前线程没有持有这个锁        &#125;    &#125;&#125;

