Java SE 7 以后新的 try-with-resources 异常处理机制，资源的声明在 resources 块，且只能在 try 语句块内使用声明的资源。
当程序运行离开 try 语句块时，声明的资源会按照创建顺序的逆序自动关闭。
可以调用 public final Java.lang.Throwable[] getSuppressed() 函数来检索被抑制的异常。
public class Java7After &#123;    public static void main(String[] args) throws Exception &#123;//        method(null);//        method(SwitchConstant.OPEN_CATCH.name());//        method(SwitchConstant.OPEN_FINALLY.name());//        method(SwitchConstant.OPEN_ALL.name());    &#125;    public static void method(String openStr) throws Exception &#123;        try (                /**                 * 我称之为&#x27;resources块&#x27;                 * 在此处声明一个或多个try语句的资源。                 * 所有实现 java.lang.AutoCloseable 接口的类都可以在 try-with-resources 结构中使用。                 * 当程序运行离开try语句块时，声明的资源会按照创建顺序的逆序自动关闭。                 * 如下两个资源：bos先关闭，bis后关闭。                 */                CustomAutoClosable customAutoClosable = new CustomAutoClosable();                CustomAutoClosable customAutoClosable2 = new CustomAutoClosable()        ) &#123;            System.out.println(&quot;执行顺序:1 -- try块打印&quot;);            throw new IOException(&quot;try块异常 -- try块抛出异常, resources块异常附加到为了传递此异常而被抑制的异常(Throwable.addSuppressed)&quot;);        &#125; catch (IOException e) &#123;            System.out.println(&quot;执行顺序:2 -- catch块打印&quot;);            // Console中文本流的顺序问题            e.printStackTrace(System.out);            int num = e.getSuppressed().length;            StringBuilder stringBuilder = new StringBuilder();            stringBuilder.append(&quot;执行顺序:3 -- catch块捕捉到异常:\n&quot;);            stringBuilder.append(&quot;\t\t\t\t\t&quot; + &quot;try块异常:\n&quot;);            stringBuilder.append(&quot;\t\t\t\t\t\t&quot; + e.getMessage() + &quot;\n&quot;);            stringBuilder.append(&quot;\t\t\t\t\t&quot; + &quot;try块异常中被抑制的&quot; + num + &quot;个resources块异常:&quot;);            for (Throwable throwable : e.getSuppressed()) &#123;                stringBuilder.append(&quot;\n\t\t\t\t\t\t&quot;);                stringBuilder.append(throwable.getMessage());            &#125;            System.out.println(stringBuilder);            boolean condition = !StringUtils.isEmpty(openStr) &amp;&amp; (openStr.equals(SwitchConstant.OPEN_ALL.name()) || openStr.equals(SwitchConstant.OPEN_CATCH.name()));            if (condition) &#123;                throw new IOException(&quot;catch块异常 -- catch块抛出新异常并向上传递; 捕捉到的try块异常不再传递, 即被忽略&quot;);            &#125;        &#125; finally &#123;            System.out.println(&quot;执行顺序:4 -- finally块打印&quot;);            boolean condition = !StringUtils.isEmpty(openStr) &amp;&amp; (openStr.equals(SwitchConstant.OPEN_ALL.name()) || openStr.equals(SwitchConstant.OPEN_FINALLY.name()));            if (condition) &#123;                throw new IOException(&quot;finally块异常 -- finally块抛出异常并向上传递, catch块异常不再传递, 即被忽略&quot;);            &#125;        &#125;    &#125;    /**     * 自定义CustomAutoClosable，实现AutoCloseable接口，观察close方法的执行时机。     */    static class CustomAutoClosable implements AutoCloseable &#123;        @Override        public void close() throws Exception &#123;            System.out.println(&quot;\t&quot; + &quot;资源关闭打印&quot;);            throw new Exception(&quot;资源关闭异常&quot;);        &#125;    &#125;&#125;

