Lombok用法Lombok注解说明官网：https://projectlombok.org/features/all

val：用在局部变量前面，相当于将变量声明为final
@NonNull：给方法参数增加这个注解会自动在方法内对该参数进行是否为空的校验，如果为空，则抛出NPE（NullPointerException）
@Cleanup：自动管理资源，用在局部变量之前，在当前变量范围内即将执行完毕退出之前会自动清理资源，自动生成try-finally这样的代码来关闭流
@Getter/@Setter：用在属性上，再也不用自己手写setter和getter方法了，还可以指定访问范围
@ToString：用在类上，可以自动覆写toString方法，当然还可以加其他参数，例如@ToString(exclude&#x3D;”id”)排除id属性，或者@ToString(callSuper&#x3D;true, includeFieldNames&#x3D;true)调用父类的toString方法，包含所有属性
@EqualsAndHashCode：用在类上，自动生成equals方法和hashCode方法
@NoArgsConstructor, @RequiredArgsConstructor and @AllArgsConstructor：用在类上，自动生成无参构造和使用所有参数的构造函数以及把所有@NonNull属性作为参数的构造函数，如果指定staticName &#x3D; “of”参数，同时还会生成一个返回类对象的静态工厂方法，比使用构造函数方便很多
@Data：注解在类上，相当于同时使用了@ToString、@EqualsAndHashCode、@Getter、@Setter和@RequiredArgsConstrutor这些注解，对于POJO类十分有用
@Value：用在类上，是@Data的不可变形式，相当于为属性添加final声明，只提供getter方法，而不提供setter方法
@Builder：用在类、构造器、方法上，为你提供复杂的builder APIs，让你可以像如下方式一样调用Person.builder().name(&quot;Adam Savage&quot;).city(&quot;San Francisco&quot;).job(&quot;Mythbusters&quot;).job(&quot;Unchained Reaction&quot;).build();更多说明参考Builder
@SneakyThrows：自动抛受检异常，而无需显式在方法上使用throws语句
@Synchronized：用在方法上，将方法声明为同步的，并自动加锁，而锁对象是一个私有的属性$lock或$LOCK，而java中的synchronized关键字锁对象是this，锁在this或者自己的类对象上存在副作用，就是你不能阻止非受控代码去锁this或者类对象，这可能会导致竞争条件或者其它线程错误
@Getter(lazy=true)：可以替代经典的Double Check Lock样板代码
@Log：根据不同的注解生成不同类型的log对象，但是实例名称都是log，有六种可选实现类
@CommonsLog Creates log &#x3D; org.apache.commons.logging.LogFactory.getLog(LogExample.class);
@Log Creates log &#x3D; java.util.logging.Logger.getLogger(LogExample.class.getName());
@Log4j Creates log &#x3D; org.apache.log4j.Logger.getLogger(LogExample.class);
@Log4j2 Creates log &#x3D; org.apache.logging.log4j.LogManager.getLogger(LogExample.class);
@Slf4j Creates log &#x3D; org.slf4j.LoggerFactory.getLogger(LogExample.class);
@XSlf4j Creates log &#x3D; org.slf4j.ext.XLoggerFactory.getXLogger(LogExample.class);

get、set方法public class FlagEntity &#123;	/**	 * 【0】是否为服务应用:1是0否，【1】是否为app-手机应用:1是0否，【2】是否为pc-PC网页应用:1是0否，【3】是否置顶(默认应用):1是0否	 */	private String flag;	/**************************** 所属系统 ****************************/	/**	 * flag【0】是否是服务应用	 */	private String flagIsServiceApp;	/**	 * flag【1】是否是手机应用	 */	private String flagIsMobileApp;	/**	 * flag【2】是否是网页应用	 */	private String flagIsWebApp;	/**	 * flag【3】是否置顶(默认应用)	 */	private String flagIsTopApp;	/**************************** 所属系统 ****************************/	public void initFlag() &#123;		StringBuilder flag = new StringBuilder();		if (this.flagIsServiceApp == null) &#123;			this.flagIsServiceApp = &quot;0&quot;;		&#125;		if (this.flagIsMobileApp == null) &#123;			this.flagIsMobileApp = &quot;0&quot;;		&#125;		if (this.flagIsWebApp == null) &#123;			this.flagIsWebApp = &quot;0&quot;;		&#125;		if (this.flagIsTopApp == null) &#123;			this.flagIsTopApp = &quot;0&quot;;		&#125;		flag.append(this.flagIsServiceApp).append(this.flagIsMobileApp).append(this.flagIsWebApp)				.append(this.flagIsTopApp).append(&quot;000000&quot;);		setFlag(flag.toString());	&#125;    	public String getFlag() &#123;		return flag;	&#125;	public void setFlag(String flag) &#123;		if (flag == null) &#123;			this.flag = flag;			return;		&#125;		// 长度校验		if (flag.length() != 10) &#123;			throw new IllegalArgumentException(&quot;Illegal flag length&quot;);		&#125;		// 内容校验，只能为数字		if (!flag.matches(&quot;^[0-9]*$&quot;)) &#123;			throw new IllegalArgumentException(&quot;Only numbers are allowed for flag&quot;);		&#125;		this.flag = flag;		this.flagIsServiceApp = this.flag.substring(0, 1);		this.flagIsMobileApp = this.flag.substring(1, 2);		this.flagIsWebApp = this.flag.substring(2, 3);		this.flagIsTopApp = this.flag.substring(3, 4);	&#125;	public String getFlagIsServiceApp() &#123;		if (StringUtils.isNotBlank(this.flagIsServiceApp)) &#123;			return this.flagIsServiceApp;		&#125;		if (StringUtils.isNotBlank(this.flag)) &#123;			return this.flag.substring(0, 1);		&#125;		return null;	&#125;	public void setFlagIsServiceApp(String flagIsServiceApp) &#123;		this.flagIsServiceApp = flagIsServiceApp;		if (StringUtils.isNotBlank(this.flag)) &#123;			this.flag = flagIsServiceApp + this.flag.substring(1);		&#125;	&#125;	public String getFlagIsMobileApp() &#123;		if (StringUtils.isNotBlank(this.flagIsMobileApp)) &#123;			return this.flagIsMobileApp;		&#125;		if (StringUtils.isNotBlank(this.flag)) &#123;			return this.flag.substring(1, 2);		&#125;		return null;	&#125;	public void setFlagIsMobileApp(String flagIsMobileApp) &#123;		this.flagIsMobileApp = flagIsMobileApp;		if (StringUtils.isNotBlank(this.flag)) &#123;			this.flag = this.flag.substring(0, 1) + flagIsMobileApp + this.flag.substring(2);		&#125;	&#125;	public String getFlagIsWebApp() &#123;		if (StringUtils.isNotBlank(this.flagIsWebApp)) &#123;			return this.flagIsWebApp;		&#125;		if (StringUtils.isNotBlank(this.flag)) &#123;			return this.flag.substring(2, 3);		&#125;		return null;	&#125;	public void setFlagIsWebApp(String flagIsWebApp) &#123;		this.flagIsWebApp = flagIsWebApp;		if (StringUtils.isNotBlank(this.flag)) &#123;			this.flag = this.flag.substring(0, 2) + flagIsWebApp + this.flag.substring(3);		&#125;	&#125;	public String getFlagIsTopApp() &#123;		if (StringUtils.isNotBlank(this.flagIsTopApp)) &#123;			return this.flagIsTopApp;		&#125;		if (StringUtils.isNotBlank(this.flag)) &#123;			return this.flag.substring(3, 4);		&#125;		return null;	&#125;	public void setFlagIsTopApp(String flagIsTopApp) &#123;		this.flagIsTopApp = flagIsTopApp;		if (StringUtils.isNotBlank(this.flag)) &#123;			this.flag = this.flag.substring(0, 3) + flagIsTopApp + this.flag.substring(4);		&#125;	&#125;&#125;

