全部-- DBA/ALL/USER/V_$/GV_$/SESSION/INDEX开头的绝大部分都是视图-- DBA_TABLES意为DBA拥有的或可以访问的所有的关系表。-- ALL_TABLES意为某一用户拥有的或可以访问的所有的关系表。-- USER_TABLES意为某一用户所拥有的所有的关系表。-- 当某一用户本身就为数据库DBA时，DBA_TABLES与ALL_TABLES等价。-- DBA_TABLES &gt;= ALL_TABLES &gt;= USER_TABLES-- 需要注意的是在ORACLE数据库中大小写是敏感的，而此三表中数据默认都是大写的，所以在进行查询的时候注意小写的数据可能会造成数据无法查到。SELECT * FROM dba_views WHERE view_name LIKE &#x27;DBA%&#x27;;SELECT * FROM dba_views WHERE view_name LIKE &#x27;ALL%&#x27;;SELECT * FROM dba_views WHERE view_name LIKE &#x27;USER%&#x27;;SELECT * FROM dba_views WHERE view_name LIKE &#x27;V_$%&#x27;; -- 针对某个实例的视图SELECT * FROM dba_views WHERE view_name LIKE &#x27;GV_$%&#x27;; -- 全局视图，针对多个实例环境SELECT * FROM dba_views WHERE view_name LIKE &#x27;SESSION%&#x27;;SELECT * FROM dba_views WHERE view_name LIKE &#x27;INDEX%&#x27;;SELECT count(1) FROM dba_tables;SELECT count(1) FROM all_tables;SELECT count(1) FROM user_tables;-- V$/GV$开头的绝大部分都是V_$/GV_$表的别名SELECT * FROM dba_synonyms WHERE synonym_name LIKE &#x27;V$%&#x27;;SELECT * FROM dba_synonyms WHERE synonym_name LIKE &#x27;GV$%&#x27;;-- X$没有对应的X_$SELECT * FROM dba_synonyms WHERE synonym_name LIKE &#x27;X$%&#x27;;-- 比较常用的DBA开头的视图有select * from dba_users; --数据库用户信息select * from dba_roles; --角色信息select * from dba_segments; --表段信息select * from dba_extents; --数据区信息select * from dba_objects; --数据库对象信息select * from dba_lobs; --lob数据信息select * from dba_tablespaces; --数据库表空间信息select * from dba_data_files; --数据文件设置信息select * from dba_temp_files; --临时数据文件信息select * from dba_rollback_segs; --回滚段信息select * from dba_ts_quotas; --用户表空间配额信息select * from dba_free_space; --数据库空闲空间信息select * from dba_profiles; --数据库用户资源限制信息select * from dba_sys_privs; --用户的系统权限信息select * from dba_tab_privs; --用户具有的对象权限信息select * from dba_col_privs; --用户具有的列对象权限信息select * from dba_role_privs; --用户具有的角色信息select * from dba_audit_trail; --审计跟踪记录信息select * from dba_stmt_audit_opts; --审计设置信息select * from dba_audit_object; --对象审计结果信息select * from dba_audit_session; --会话审计结果信息select * from dba_indexes; --用户模式的索引信息-- 比较常用的ALL开头的视图有select * from all_users; --数据库所有用户的信息select * from all_objects; --数据库所有的对象的信息select * from all_def_audit_opts; --所有默认的审计设置信息select * from all_tables; --所有的表对象信息select * from all_indexes; --所有的数据库对象索引的信息select * from all_tab_comments; --查询所有用户的表,视图等select * from all_tab_columns; --查询所有用户的表的列名等信息(详细但是没有备注)select * from all_col_comments; --查询所有用户的表的列名和注释select * from all_constraints; --查询所有用户的表的约束select * from all_cons_columns; --查询所有用户的表的约束列-- 比较常用的ALL开头的视图有select * from user_objects; --用户对象信息select * from user_source; --数据库用户的所有资源对象信息select * from user_segments; --用户的表段信息select * from user_tables; --用户的表对象信息select * from user_tab_columns; --用户的表列信息select * from user_constraints; --用户的对象约束信息select * from user_sys_privs; --当前用户的系统权限信息select * from user_tab_privs; --当前用户的对象权限信息select * from user_col_privs; --当前用户的表列权限信息select * from user_col_comments; -- 查询本用户的表的列名和注释select * from user_role_privs; --当前用户的角色权限信息select * from user_indexes; --用户的索引信息select * from user_ind_columns; --用户的索引对应的表列信息select * from user_cons_columns; --用户的约束对应的表列信息select * from user_clusters; --用户的所有簇信息select * from user_clu_columns; --用户的簇所包含的内容信息select * from user_cluster_hash_expressions; --散列簇的信息-- 比较常用的V$开头的别名有select * from v$database; --数据库信息select * from v$datafile; --数据文件信息select * from v$controlfile; --控制文件信息select * from v$logfile; --重做日志信息select * from v$instance; --数据库实例信息select * from v$log; --日志组信息select * from v$loghist; --日志历史信息select * from v$sga; --数据库SGA信息select * from v$parameter; --初始化参数信息select * from v$process; --数据库服务器进程信息select * from v$bgprocess; --数据库后台进程信息select * from v$controlfile_record_section; --控制文件记载的各部分信息select * from v$thread; --线程信息select * from v$datafile_header; --数据文件头所记载的信息select * from v$archived_log; --归档日志信息select * from v$archive_dest; --归档日志的设置信息select * from v$logmnr_contents; --归档日志分析的DML DDL结果信息select * from v$logmnr_dictionary; --日志分析的字典文件信息select * from v$logmnr_logs; --日志分析的日志列表信息select * from v$tablespace; --表空间信息select * from v$tempfile; --临时文件信息select * from v$filestat; --数据文件的I/O统计信息select * from v$undostat; --Undo数据信息select * from v$rollname; --在线回滚段信息select * from v$session; --会话信息select * from v$transaction; --事务信息select * from v$rollstat; --回滚段统计信息select * from v$pwfile_users; --特权用户信息select * from v$sqlarea; --当前查询过的sql语句访问过的资源及相关的信息select * from v$sql; --与v$sqlarea基本相同的相关信息select * from v$sysstat; --数据库系统状态信息-- 比较常用的SESSION开头的视图有select * from session_roles; --会话的角色信息select * from session_privs; --会话的权限信息-- 比较常用的INDEX开头的视图有select * from index_stats; --索引的设置和存储信息-- 伪表，参考oracle 中 dual 详解：http://blog.csdn.net/ozhouhui/article/details/7935196select * from dual; --系统伪列表信息select sysdate from dual; --可将Sysdate视为一个其结果为当前日期和时间的函数，在任何可以使用Oracle函数的地方都可以使用Sysdate。也可以将它视为每个表的一个隐藏的列或伪列。select current_date from dual; --报告会话的时区中的系统日期。注：可以设置自己的时区，以区别于数据库的时区。select SYSTIMESTAMP from dual; --报告TIMESTAMP数据类型格式的系统日期。-- 系统权限-- GRANTEE 接受该权限的用户名 -- OWNER 对象的拥有者 -- GRANTOR 赋予权限的用户SELECT * FROM dba_sys_privs WHERE grantee = &#x27;SYS&#x27;;SELECT * FROM dba_sys_privs WHERE grantee = &#x27;CONNECT&#x27;;SELECT * FROM dba_sys_privs WHERE grantee = &#x27;RESOURCE&#x27;;-- 角色权限-- 查看某个用户有哪些角色select * from dba_role_privs where grantee=&#x27;SYS&#x27;;-- 查看某个角色被赋予了哪些用户SELECT * FROM dba_role_privs WHERE granted_role = &#x27;DBA&#x27;;-- 对象权限SELECT * FROM dba_tab_privs;-- 授予某个用户某些角色GRANT connect,resource TO &#x27;USER&#x27;;GRANT dba to &#x27;USER&#x27;; --给普通用户授予dba角色时，要重新连接才能生效REVOKE dba to &#x27;USER&#x27;;-- 直接授予某个用户某些权限GRANT CREATE VIEW TO &#x27;USER&#x27;;-- 查看某个系统用户是否有SYSDBA或者SYSOPER权限-- oracle:DBA,SYSDBA,SYSOPER三者的区别：http://blog.chinaunix.net/uid-22457844-id-3045741.htmlselect * from V$PWFILE_USERS;-- 锁定、解锁用户SELECT * FROM dba_users WHERE username = &#x27;SCOTT&#x27;;ALTER USER SCOTT account LOCK; --锁定用户ALTER USER SCOTT account UNLOCK; --解锁用户COMMIT;-- oracle10g 修改用户密码: http://blog.163.com/benbenfafa_88/blog/static/64930162200972594612972/-- User Default Password Check in Oracle 11g: http://www.dbform.com/html/2009/673.htmlSELECT password FROM dba_users WHERE username = &#x27;SCOTT&#x27;;alter user SCOTT identified by new_password; --修改用户密码-- SERVICE_NAMES: http://docs.oracle.com/database/121/REFRN/GUID-AC956707-D568-4F8A-BF2E-99BA41E0A64F.htm#REFRN10194SELECT * FROM global_name; -- 查看oracle的全局数据库名SELECT * FROM v$database; -- 查看数据库名 show parameter db_name;-- 数据库实例名对应着SID-- SID: http://docs.oracle.com/database/121/LADBI/glossary.htm#LADBI8021-- linux下在配置oracle环境变量的情况可以使用 echo $ORACLE_SID,如果没有可以使用ps -ef |grep oracle 来查询，结果中的xxxx就是对应的SID。-- oracle    2548     1  0 Aug17 ?        00:00:00 ora_pmon_xxxx-- 在windows环境下,oracle是以后台服务的方式被管理的,所以看&quot;控制面板-&gt;管理工具-&gt;服务 里面的名称:&quot;OracleServiceORCL&quot;,则ORCL就是sid;SELECT * FROM v$instance; --查看数据库实例名 show parameter instance_name;select instance from v$thread;-- show parameter是oracle的命令，不是标准SQL语句-- 可以在sqlplus或者pl/sql dev的命令窗口执行-- show parameter aaaa;等价于SELECT * FROM v$parameter WHERE name like &#x27;%aaaa%&#x27;;SELECT * FROM v$parameter WHERE name like &#x27;%name%&#x27;; --等价于show parameter name;select * from v$parameter where name like &#x27;%db_domain%&#x27;; --查询数据库域名select username from all_users where username like &#x27;%SCOTT%&#x27;;drop user SCOTT cascade;commit;-- ERROR at line 1:-- ORA-01940: cannot drop a user that is currently connectedselect &#x27;ALTER SYSTEM KILL SESSION &#x27;||&#x27;&#x27;&#x27;&#x27;||SID||&#x27;,&#x27;||SERIAL#||&#x27;&#x27;&#x27;&#x27;||&#x27;;&#x27; as KILLER from v$session where username=&#x27;SCOTT&#x27;;-- KILLER-- ALTER SYSTEM KILL SESSION &#x27;363,35&#x27;;-- ALTER SYSTEM KILL SESSION &#x27;364,51&#x27;;commit;select * from dba_roles where role like &#x27;%CONNECT%&#x27;;drop role CONNECT;commit;select * from dba_tablespaces where tablespace_name like &#x27;EXAMPLE&#x27;;drop tablespace EXAMPLE including contents and datafiles cascade constraints ;-- including contents 删除表空间中的内容，如果删除表空间之前表空间中有内容，而未加此参数，表空间删不掉，所以习惯性的加此参数。-- including datafiles 删除表空间中的数据文件。-- cascade constraints 同时删除 tablespace 中表的外键参照。-- 如何创建dblink和视图-- http://docs.oracle.com/database/121/SQLRF/statements_5006.htm#i2061505-- 如果需要创建全局 DBLink，则需要先确定用户有创建 dblink 的权限：select * from user_sys_privs where privilege like upper(&#x27;%DATABASE LINK%&#x27;);-- 如果没有，则需要使用 sysdba 角色给用户赋权：grant create public database link to dbusername;-- 如果创建全局 dblink，必须使用 systm 或 sys 用户，在 database 前加 public。create /* public */ database link dblink1connect to dbusername identified by dbpasswordusing &#x27;(DESCRIPTION =(ADDRESS_LIST =(ADDRESS =(PROTOCOL = TCP)(HOST = 192.168.0.1)(PORT = 1521)))(CONNECT_DATA =(SERVICE_NAME = orcl)))&#x27;;-- 创建dblink后，就可以直接在dblink上创建视图create or replace view cptp as (select SJDH from dbusername.cptp@dblink1); drop view cptp;-- 锁表查询SQLSELECT object_name, machine, s.sid, s.serial#FROM gv$locked_object l, dba_objects o, gv$session sWHERE l.object_id　= o.object_idAND l.session_id = s.sid;-- 解除锁表alter system kill session &#x27;sid, serial#&#x27;;-- 备份某个表create table new_table as select * from old_table;-- 查看数据库是否在rac环境的集群中的show parameter cluster_database;select * from v$parameter where name = &#x27;cluster_database&#x27;;-- 列操作-- 增加和修改列不需要加关键字COLUMN-- 删除单列的话，一定要加COLUMN，删除多列的时候，不能加COLUMN关键字-- 增加一列alter table emp4 add test varchar2(10);-- 修改一列alter table emp4 modify test varchar2(20);-- 删除一列alter table emp4 drop column test;-- 增加多列alter table emp4 add (test varchar2(10),test2 number);-- 修改多列alter table emp4 modify (test varchar2(20),test2 varchar2(20));-- 删除多列alter table emp4 drop (test,test2);-- Windows下以管理员身份启动数据库net start oracleserviceorcl -- 后面的orcl是你安装的数据库实例名net start oracleoradb11g_home1tnslistener --非必须-- linux下以sysdba用户登录，然后启动数据库sqlplus / as sysdbastartup-- sqlplus登陆方式sqlplus / as sysdba --以操作系统权限认证的oracle sys管理员登陆sqlplus /nologconn / as sysdba --以操作系统权限认证的oracle sys管理员登陆sqlplus sys/password@orcl as sysdba --以sys用户登陆必须使用as sysdbasqlplus /nolog --不在cmd或者teminal当中暴露密码的登陆方式conn sys/password as sysdbasqlplus --不显露密码的方式登陆Enter user-name：sysEnter password：password as sysdba --以sys用户登陆的话 必须要加上as sysdba子句sqlplus scott/tiger@orcl --非管理员用户登陆desc v$database; --查询v$database数据库的表结构--在sqlplus中执行sql脚本，下面两种方式都可以START file_name@file_name--判断表是否存在，如果存在则删除declare      num   number;begin      select count(1) into num from all_tables where TABLE_NAME = &#x27;EMP&#x27; and OWNER=&#x27;SCOTT&#x27;;      if   num=1   then          execute immediate &#x27;drop table EMP&#x27;;      end   if;end;/--创建表CREATE TABLE EMP       (EMPNO NUMBER(4) NOT NULL,        ENAME VARCHAR2(10),        JOB VARCHAR2(9),        MGR NUMBER(4),        HIREDATE DATE,        SAL NUMBER(7, 2),        COMM NUMBER(7, 2),        DEPTNO NUMBER(2));可以将上述存储过程加载到每一个create table前面。--ORACLE 判断序列是否存在,如果存在就删除declare V_NUM number;BEGIN  ----多次删除时，每次都将v_num设置成为0    V_NUM := 0;    ----判断序列 seq_name_1 是否存在（区分大小写）    select count(0) into V_NUM from user_sequences where sequence_name = &#x27;SEQ_BUSINESS_PROCESS_INDEX_ID&#x27;;    ----如果存在立即删除    if V_NUM &gt; 0 then    execute immediate &#x27;DROP SEQUENCE  SEQ_BUSINESS_PROCESS_INDEX_ID&#x27;;    end if;END;-- 设置sqlplus模式显示总行数show pagesize; --查看当前的pagesizeset pagesize 300;-- 设置sqlplus模式显示行宽度show linesize; --查看当前的linesizeset linesize 300;-- 修改安装目录glogin.sql文件才能保证之前的设置永久生效set pagesize 300;set linesize 300;-- 删除表对象select &#x27;drop table &#x27;||segment_name from dba_segments where owner=&#x27;VPMUSER&#x27; and segment_type=&#x27;TABLE&#x27;;-- 创建表对象select&#x27;create table &#x27;||segment_name || &#x27; as select * from &#x27;||segment_name ||&#x27;@DBLINK&#x27;from dba_segments where owner=&#x27;VPMUSER&#x27; and segment_type=&#x27;TABLE&#x27;;-- 检查表是否完整导入select segment_name from dba_segments@aaa where owner=&#x27;VPMUSER&#x27; and segment_type=&#x27;TABLE&#x27;and (segment_name not like &#x27;BIN$%&#x27;and segment_name not like &#x27;%201%&#x27;)minusselect segment_name from dba_segments where owner=&#x27;VPMUSER&#x27; and segment_type=&#x27;TABLE&#x27;  and segment_name not like &#x27;BIN$%&#x27;--查询用户所有表的语句1select t.table_name,t.comments from user_tab_comments t--查询用户所有表的语句2:select r1, r2, r3, r5from (select a.table_name r1, a.column_name r2, a.comments r3          from user_col_comments a),       (select t.table_name r4, t.comments r5 from user_tab_comments t)where r4 = r1-- 查找表的所有索引（包括索引名，类型，构成列）：select t.*,i.index_type from user_ind_columns t,user_indexes i where t.index_name = i.index_name and t.table_name = i.table_name and t.table_name = 要查询的表-- 查找表的主键（包括名称，构成列）：select cu.* from user_cons_columns cu, user_constraints au where cu.constraint_name = au.constraint_name and au.constraint_type = &#x27;P&#x27; and au.table_name = 要查询的表-- 查找表的唯一性约束（包括名称，构成列）：select column_name from user_cons_columns cu, user_constraints au where cu.constraint_name = au.constraint_name and au.constraint_type = &#x27;U&#x27; and au.table_name = 要查询的表-- 查找表的外键（包括名称，引用表的表名和对应的键名，下面是分成多步查询）：select * from user_constraints c where c.constraint_type = &#x27;R&#x27; and c.table_name = 要查询的表-- 查询外键约束的列名：select * from user_cons_columns cl where cl.constraint_name = 外键名称-- 查询引用表的键的列名：select * from user_cons_columns cl where cl.constraint_name = 外键引用表的键名-- 查询表的所有列及其属性select t.*,c.COMMENTS from user_tab_columns t,user_col_comments c where t.table_name = c.table_name and t.column_name = c.column_name and t.table_name = 要查询的表    --备份表数据create table emp as select * from scott.emp--还原表数据insert into emp select * from scott.emp    --查看已经执行过的sql这些是存在共享池中的，用户名需要大写，必须具有DBA 的权限select * from v$sqlarea t where t.PARSING_SCHEMA_NAME in (&#x27;用户名&#x27;) order by t.LAST_ACTIVE_TIME desc        --ORACLE11G 字符集更改（这里更改为AL32UTF8）sqlplus sys as sysdba--执行下面命令，有可能造成数据库中已有数据混乱的情况，所以在进行操作前，要进行数据库的备份操作shutdown immediate;STARTUP MOUNT;ALTER SESSION SET SQL_TRACE=TRUE;ALTER SYSTEM ENABLE RESTRICTED SESSION;ALTER SYSTEM SET JOB_QUEUE_PROCESSES=0;ALTER SYSTEM SET AQ_TM_PROCESSES=0;ALTER DATABASE OPEN;ALTER DATABASE character set INTERNAL_USE AL32UTF8;ALTER SESSION SET SQL_TRACE=FALSE;shutdown immediate;startup;--察看 NLS_LANG 信息：SELECT parameter, value FROM v$nls_parameters WHERE parameter LIKE &#x27;%CHARACTERSET&#x27;;UPDATE STAFFSET MODIFY_TIME = TO_DATE(&#x27;2016/04/22 00:01:00&#x27;, &#x27;yyyy/MM/dd hh24:mi:ss&#x27;)WHERE MODIFY_TIME &lt; TO_DATE(&#x27;2016/04/22 00:01:00&#x27;, &#x27;yyyy/MM/dd hh24:mi:ss&#x27;);UPDATE STAFFSET MODIFY_TIME = TO_TIMESTAMP(&#x27;19-03-2008 02:36:00.360000&#x27;, &#x27;dd-MM-yyyy hh24:mi:ss.ff&#x27;)WHERE STAFF_ID = &#x27;01&#x27;;

