行转列decode+wm_concatselect t.name,       t.year,       to_char(wm_concat(t.Q1)) Q1,       to_char(wm_concat(t.Q2)) Q2,       to_char(wm_concat(t.Q3)) Q3,       to_char(wm_concat(t.Q4)) Q4  from (select t.name,               t.year,               decode(t.quarter, &#x27;Q1&#x27;, sum(sales), null) Q1,               decode(t.quarter, &#x27;Q2&#x27;, sum(sales), null) Q2,               decode(t.quarter, &#x27;Q3&#x27;, sum(sales), null) Q3,               decode(t.quarter, &#x27;Q4&#x27;, sum(sales), null) Q4          from t_fruit_row t         group by t.name, t.year, t.quarter         order by name) t group by t.name, t.year order by t.year, t.name; -- 与下面结果对比select * from t_fruit_column order by year, name;

pivot(行转列)SELECT ...  FROM  ...PIVOT [XML]   (pivot_clause    pivot_for_clause    pivot_in_clause ) WHERE ...

按照序号编写好理解 
3、 pivot_clause：指定聚合函数，对值进行聚合。允许指定多个，决定转换后列的倍数。
1、 pivot_for_clause：指定行转列的字段，允许指定多字段。
2、 pivot_in_clause：对 pivot_for_clause 指定的字段进行过滤，只将满足条件的行转成列。可以是固定值、any、子查询(未测试成功)。
转换后的列数 &#x3D; pivot_clause * pivot_in_clause 
-- 单字段转列select *  from (select name, year, quarter, sales from t_fruit_row) tpivot(sum(t.sales) as total   for quarter in(&#x27;Q1&#x27; as Q1, &#x27;Q2&#x27; as Q2, &#x27;Q3&#x27; as Q3, &#x27;Q4&#x27; as Q4)) t2 order by t2.year, t2.name; -- 与下面结果对比select * from t_fruit_column order by year, name;-- 多字段转列select *  from (select name, year, quarter, sales from t_fruit_row) tpivot(sum(t.sales) as total   for(year, quarter) in((&#x27;2020&#x27;, &#x27;Q1&#x27;) as &quot;2020_Q1&quot;,                         (&#x27;2020&#x27;, &#x27;Q2&#x27;) as &quot;2020_Q2&quot;,                         (&#x27;2020&#x27;, &#x27;Q3&#x27;) as &quot;2020_Q3&quot;,                         (&#x27;2020&#x27;, &#x27;Q4&#x27;) as &quot;2020_Q4&quot;,                         (&#x27;2021&#x27;, &#x27;Q1&#x27;) as &quot;2021_Q1&quot;,                         (&#x27;2021&#x27;, &#x27;Q2&#x27;) as &quot;2021_Q2&quot;,                         (&#x27;2021&#x27;, &#x27;Q3&#x27;) as &quot;2021_Q3&quot;,                         (&#x27;2021&#x27;, &#x27;Q4&#x27;) as &quot;2021_Q4&quot;)) t2 order by t2.name;

统计各季度的总销量和该季度最大销量：行转多列 
select *  from (select name, quarter, sales from t_fruit_row) tpivot(sum(t.sales) as total, max(sales) as max   for quarter in(&#x27;Q1&#x27; as Q1, &#x27;Q2&#x27; as Q2, &#x27;Q3&#x27; as Q3, &#x27;Q4&#x27; as Q4)) t2 order by t2.name;

按照oracle的文档，pivot语句中in后面的列如果不固定，只能使用xml格式的返回结果
-- 单统计列select *  from (select name, year, quarter, sales from t_fruit_row) tpivot xml(sum(t.sales) as total   for quarter in(any)) t2 order by t2.year, t2.name;-- 多统计列select *  from (select name, year, quarter, sales from t_fruit_row) tpivot xml(sum(t.sales) as total   for(year, quarter) in(any, any)) t2 order by t2.name;

列转行union allselect t.name, t.year, &#x27;Q1&#x27; as quarter, t.Q1 as sales from t_fruit_column t union allselect t.name, t.year, &#x27;Q2&#x27; as quarter, t.Q2 as sales from t_fruit_column t union allselect t.name, t.year, &#x27;Q3&#x27; as quarter, t.Q3 as sales from t_fruit_column t union allselect t.name, t.year, &#x27;Q4&#x27; as quarter, t.Q4 as sales from t_fruit_column t order by name, year, quarter;-- 与下面结果对比select * from t_fruit_row order by name, year, quarter;

unpivot(列转行)SELECT ...  FROM  ...UNPIVOT [INCLUDE|EXCLUDE NULLS]   (unpivot_clause    unpivot_for_clause    unpivot_in_clause ) WHERE ...

INCLUDE NULLS：保留null数据；
EXCLUDE NULLS（默认）：不保留null数据。
按照序号编写好理解 
3、 unpivot_clause：指定原列值对应的新字段名。
2、 unpivot_for_clause：指定列转行后的字段名，允许多个。
1、 unpivot_in_clause：指定具体列到行的字段名。
select *  from (select name, year, q1, q2, q3, q4 from t_fruit_column) tunpivot INCLUDE NULLS (sales   for quarter in(q1 as &#x27;第一季度&#x27;, q2, q3, q4)) t2 order by t2.name, t2.year, t2.quarter;-- 与下面结果对比select * from t_fruit_row order by name, year, quarter;

