重定向插入数据(触发器)定义一个trigger，把对主表的数据插入操作重定向到对应的分区表。
创建触发器CREATE TRIGGER trig_insert_a_userBEFORE INSERTON a_userFOR EACH ROWEXECUTE PROCEDURE func_insert_a_user();

创建分区函数CREATE OR REPLACE FUNCTION func_insert_a_user()returns trigger as$body$BEGIN  IF NEW.sex = 1    THEN      INSERT INTO a_user_1 VALUES (NEW.*);  ELSIF NEW.sex = 2    THEN      INSERT INTO a_user_2 VALUES (NEW.*);  END IF;  RETURN NULL;END;$body$LANGUAGE plpgsql;

