执行上述sql，此时不满足条件的数据丢弃，也可以使用other表接收这些数据。
需求：所有数据都应按照规律存到对应的子表（分区表）中，若不存在这样的表要实现自动新建。
重定向插入数据(触发器)-终极创建触发器CREATE TRIGGER trig_insert_a_userBEFORE INSERTON a_userFOR EACH ROWEXECUTE PROCEDURE func_insert_a_user();

创建分区函数 自动创建分区表并插入数据： 
CREATE OR REPLACE FUNCTION func_insert_a_user()returns trigger as$body$DECLARE        sex_colume integer;        insert_statement TEXT;BEGIN  select NEW.sex INTO sex_colume;  insert_statement := &#x27;INSERT INTO a_user_&#x27; || sex_colume || &#x27; VALUES ($1.*)&#x27;;  execute insert_statement USING NEW;  return null;  EXCEPTION  WHEN UNDEFINED_TABLE    THEN      -- 创建分表并加限制      execute &#x27;CREATE TABLE IF NOT EXISTS a_user_&#x27; || sex_colume || &#x27; ( CHECK (sex = &#x27; || sex_colume || &#x27;) ) inherits (a_user)&#x27;;      raise notice &#x27;Create a new table a_user_%&#x27;, sex_colume;      -- 建索引      execute &#x27;CREATE UNIQUE INDEX idx_uk_a_user_&#x27; || sex_colume || &#x27;_account ON a_user_&#x27; || sex_colume || &#x27;(account)&#x27;;      execute &#x27;CREATE INDEX idx_a_user_&#x27; || sex_colume || &#x27;_account_name ON a_user_&#x27; || sex_colume || &#x27;(account, name)&#x27;;      -- 分表字段也应加索引，虽然这会命中所有记录      execute &#x27;CREATE INDEX idx_a_user_&#x27; || sex_colume || &#x27;_sex ON a_user_&#x27; || sex_colume || &#x27;(sex, account, name)&#x27;;      -- 加约束      execute &#x27;ALTER TABLE a_user_&#x27; || sex_colume || &#x27; add constraint pk_a_user_&#x27; || sex_colume || &#x27;_id primary key (id)&#x27;;      execute &#x27;ALTER TABLE a_user_&#x27; || sex_colume || &#x27; add constraint uk_a_user_&#x27; || sex_colume || &#x27;_account unique(account)&#x27;;      -- 建立分表后再次插入      execute insert_statement USING NEW;      return null;END;$body$LANGUAGE plpgsql;

